import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { addClinic, liftSingleClinicGate } from './helpers/clinics'
import { createTestDatabase, type TestDatabase } from './helpers/database'
import { seedFixture, type Fixture } from './helpers/fixtures'

/**
 * Module 9.5: who generated each report, as the Reports page reads it -
 * `report` with its `user_account ( user_email )` embed, both under RLS. No
 * migration is involved; this pins that the list's "Generated by" can only
 * ever name an account the reader may already see, and that a Clinic Admin's
 * list and its names stop at their clinic's edge.
 */

/** The page's query, as PostgREST runs the to-one embed: a lookup per row. */
const LIST = `
  select r.report_id,
         r.report_type::text as type,
         (select u.user_email from public.user_account u where u.user_id = r.user_id) as creator
    from public.report r
   order by r.report_generated_at, r.report_id`

async function account(database: TestDatabase, email: string, role: 'doctor' | 'admin') {
  const [user] = await database.asService<{ id: string }>(
    'insert into auth.users (id, email) values (gen_random_uuid(), $1) returning id',
    [email],
  )
  await database.asService(
    'insert into public.user_account (user_id, user_email, user_role) values ($1, $2, $3)',
    [user!.id, email, role],
  )
  return user!.id
}

async function report(
  database: TestDatabase,
  userId: string,
  minutesAgo: number,
  patId: string | null = null,
): Promise<string> {
  const [row] = await database.asService<{ report_id: string }>(
    `insert into public.report (user_id, report_type, pat_id, report_generated_at)
     values ($1, $2::public.report_type, $3, now() - make_interval(mins => $4))
     returning report_id`,
    [userId, patId ? 'patient_recovery' : 'system_wide', patId, minutesAgo],
  )
  return row!.report_id
}

describe('who generated a report, as a reader may see it', () => {
  let database: TestDatabase
  let fx: Fixture
  let secondAdminUserId: string
  let otherAdminUserId: string
  const id: Record<string, string> = {}

  beforeAll(async () => {
    database = await createTestDatabase()
    fx = await seedFixture(database)
    const clinicA = (await database.asService<{ clinic_id: string }>('select clinic_id from public.clinic'))[0]!
      .clinic_id

    // A second Clinic Admin at Harborview.
    secondAdminUserId = await account(database, 'noel.bautista@harborview.test', 'admin')
    await database.asService(
      `insert into public.admin (user_id, admin_first_name, admin_last_name, clinic_id)
       values ($1, 'Noel', 'Bautista', $2)`,
      [secondAdminUserId, clinicA],
    )

    // And a clinic beside it, with its own.
    await liftSingleClinicGate(database)
    const clinicB = await addClinic(database, 'Synthetic Second Clinic', 'Asia/Tokyo')
    otherAdminUserId = await account(database, 'admin.b@second.test', 'admin')
    await database.asService(
      `insert into public.admin (user_id, admin_first_name, admin_last_name, clinic_id)
       values ($1, 'Bianca', 'Ortiz', $2)`,
      [otherAdminUserId, clinicB],
    )

    id['own'] = await report(database, fx.adminUserId, 40)
    id['colleague'] = await report(database, secondAdminUserId, 30)
    id['doctor'] = await report(database, fx.doctorAUserId, 20, fx.alicePatId)
    id['elsewhere'] = await report(database, otherAdminUserId, 10)
  })

  afterAll(async () => {
    await database?.close()
  })

  it('names a Clinic Admin’s own reports and their colleagues’, by address', async () => {
    expect(await database.asUser(fx.adminUserId, LIST)).toEqual([
      { report_id: id['own'], type: 'system_wide', creator: 'admin@recoverease.test' },
      { report_id: id['colleague'], type: 'system_wide', creator: 'noel.bautista@harborview.test' },
    ])
  })

  it('shows them no other clinic’s report, and no other clinic’s account', async () => {
    const seen = await database.asUser<{ report_id: string }>(fx.adminUserId, LIST)
    expect(seen.map((row) => row.report_id)).not.toContain(id['elsewhere'])

    await expect(
      database.asUser(
        fx.adminUserId,
        'select user_email from public.user_account where user_id = $1',
        [otherAdminUserId],
      ),
    ).resolves.toEqual([])
    expect(await database.asUser(otherAdminUserId, LIST)).toEqual([
      { report_id: id['elsewhere'], type: 'system_wide', creator: 'admin.b@second.test' },
    ])
  })

  it('gives a colleague’s address, not their name, which is theirs alone', async () => {
    await expect(
      database.asUser(
        fx.adminUserId,
        'select admin_first_name from public.admin where user_id = $1',
        [secondAdminUserId],
      ),
    ).resolves.toEqual([])
  })

  it('keeps a doctor’s list to their own reports', async () => {
    expect(await database.asUser(fx.doctorAUserId, LIST)).toEqual([
      { report_id: id['doctor'], type: 'patient_recovery', creator: 'doctor.a@recoverease.test' },
    ])
    expect(await database.asUser(fx.doctorBUserId, LIST)).toEqual([])
  })
})
